<script setup lang="ts">import{ref}from"vue";import{iptvChannelRepository,iptvSourceRepository}from"@/domain/repositories";import{testSourcesBatch}from"@/domain/iptv/batchStreamTest";import type{IptvChannelRecord,IptvSourceRecord}from"@/types/records";import{protocolLabel,qualityLabel,streamStateLabel}from"@/domain/iptv/format";import StreamLinkEditDialog from"./StreamLinkEditDialog.vue";import StreamTestButton from"./StreamTestButton.vue";const props=defineProps<{channel:IptvChannelRecord;links:IptvSourceRecord[]}>();const emit=defineEmits<{changed:[IptvSourceRecord[]];channelChanged:[IptvChannelRecord];play:[]}>();const edit=ref<IptvSourceRecord|null>(null),open=ref(false),batchRunning=ref(false),batchProgress=ref(0);let batchController:AbortController|null=null;function upsert(item:IptvSourceRecord){const next=props.links.some(x=>x.id===item.id)?props.links.map(x=>x.id===item.id?item:x):[...props.links,item];emit("changed",next);open.value=false;edit.value=null}async function toggle(item:IptvSourceRecord){upsert(await iptvSourceRepository.update(item.id,{ativo:item.ativo===false})as IptvSourceRecord)}async function primary(item:IptvSourceRecord){const updated=await iptvSourceRepository.update(item.id,{prioridade:0})as IptvSourceRecord;const channel=await iptvChannelRepository.update(props.channel.id,{url_stream:item.url})as IptvChannelRecord;upsert(updated);emit("channelChanged",channel)}async function remove(item:IptvSourceRecord){if(!confirm(`Eliminar a fonte “${item.rotulo||item.url}”?`))return;await iptvSourceRepository.delete(item.id);emit("changed",props.links.filter(x=>x.id!==item.id))}async function testAll(){batchController=new AbortController();batchRunning.value=true;batchProgress.value=0;const results=await testSourcesBatch(props.links.filter(x=>x.ativo!==false),{signal:batchController.signal,onProgress:done=>batchProgress.value=done});const updated=[...props.links];for(const entry of results){const saved=await iptvSourceRepository.update(entry.link.id,{ultimo_teste_em:entry.result.testedAt,ultimo_estado:entry.result.state,metadata_extra:{ultimo_teste_browser:{elapsed_ms:entry.result.elapsedMs,content_type:entry.result.contentType,http_status:entry.result.httpStatus,message:entry.result.message}}})as IptvSourceRecord;const i=updated.findIndex(x=>x.id===saved.id);if(i>=0)updated[i]=saved}emit("changed",updated);batchRunning.value=false}function cancelBatch(){batchController?.abort()}</script><template><section class="stream-manager"><div class="section-heading"><div><p class="eyebrow">Fontes técnicas</p><h3>Links do canal</h3></div><div class="live-actions"><button class="button button-primary" type="button" @click="edit=null;open=true">Adicionar fonte</button><button class="button button-secondary" type="button" @click="emit('play')">▶ Reproduzir</button><button class="button button-secondary" type="button" :disabled="batchRunning||!links.length" @click="testAll">{{batchRunning?`Testadas ${batchProgress}/${links.length}`:"Testar todas"}}</button><button v-if="batchRunning" class="button button-secondary" type="button" @click="cancelBatch">Cancelar testes</button></div></div><p v-if="!links.length" class="field-hint">O canal usa apenas o stream principal.</p><article v-for="item in links" :key="item.id" class="stream-manager-row"><div><strong>{{item.rotulo||protocolLabel(item.tipo)}}</strong><small>{{qualityLabel(item.qualidade)}} · prioridade {{item.prioridade??1000}} · {{streamStateLabel(item.ultimo_estado)}}</small><code>{{item.url}}</code></div><div class="stream-manager-actions"><StreamTestButton :link="item" @tested="upsert"/><button class="button button-secondary" type="button" @click="edit=item;open=true">Editar</button><button class="button button-secondary" type="button" @click="primary(item)">Principal</button><button class="button button-secondary" type="button" @click="toggle(item)">{{item.ativo===false?'Ativar':'Desativar'}}</button><button class="button button-danger" type="button" @click="remove(item)">Eliminar</button></div></article><StreamLinkEditDialog :channel="channel" :link="edit" :open="open" @close="open=false;edit=null" @saved="upsert"/></section></template>
